<script lang="ts">import {createEventDispatcher} from 'svelte';import type {ChatImageDraft} from './chat-images';export let images:ChatImageDraft[]=[];export let busy=false;const dispatch=createEventDispatcher();</script>
{#if images.length}<div class="image-chips" aria-label="Attached images">{#each images as image(image.localId)}<div class="image-chip">{#if image.url}<img src={image.url} alt={image.name}/>{/if}<div><strong>{image.name}</strong><small class:error={image.status==='error'}>{image.status==='uploading'?'Uploading…':image.status==='ready'?'Ready to send':image.error||'Upload unavailable'}</small></div><button type="button" disabled={busy} aria-label={'Remove '+image.name} on:click={()=>dispatch('remove',image.localId)}>×</button></div>{/each}</div>{/if}
<style>.image-chips{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:12px}.image-chip{display:flex;align-items:center;gap:9px;border:1px solid #dce5f2;border-radius:9px;padding:7px;background:#f8faff;max-width:100%;color:#263b58}.image-chip img{width:50px;height:50px;object-fit:cover;border-radius:5px}.image-chip strong{font-size:11px;display:block;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.image-chip small{font-size:10px;color:#64748b;display:block;max-width:260px;overflow-wrap:anywhere}.image-chip small.error{color:#b4233a}.image-chip button{background:none;border:0;color:#64748b;font-size:20px;padding:3px 7px;cursor:pointer}.image-chip button:disabled{opacity:.4}.image-chip button:focus-visible{outline:2px solid #2563eb;outline-offset:2px}</style>
